// Resolve hook: the generated client imports its siblings the way a bundler
// resolves them — extensionless ("./error"). node's ESM loader does not add
// extensions, so this retry once with ".ts" for relative specifiers. It is
// used only to run the harness; it changes no generated bytes.
export async function resolve(specifier, context, next) {
  if (!specifier.startsWith(".")) return next(specifier, context);
  try {
    return await next(specifier, context);
  } catch (err) {
    if (specifier.endsWith(".ts") || specifier.endsWith(".js")) throw err;
    return next(`${specifier}.ts`, context);
  }
}
